CREATE OR REPLACE FUNCTION logistica.fn_saldo_por_coluna(p_coluna TEXT, p_filial BIGINT)
RETURNS NUMERIC LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_saldo NUMERIC;
BEGIN
    IF p_coluna NOT IN ('quantidade', 'quantidade_reservada') THEN
        RAISE EXCEPTION 'coluna nao permitida: %', p_coluna;
    END IF;
    EXECUTE format('SELECT sum(%I) FROM logistica.estoque_mov WHERE filial_id = $1', p_coluna)
       INTO v_saldo
      USING p_filial;
    RETURN coalesce(v_saldo, 0);
END;
$$;

